import{_ as e,o,c as a,a5 as r}from"./chunks/framework.B5tqjWbr.js";const p=JSON.parse('{"title":"SYS-07 电源-电控联合系统设计 - 知识检查","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"advanced","chapterTitle":"进阶专题","chapterOrder":30,"category":"进阶专题","source":"motor","visibility":"public","title":"SYS-07 电源-电控联合系统设计 - 知识检查","tags":["motor-control"],"status":"learning","summary":"**模块编号：** SYS-07 **题目数量：** 8 **验收目标：** 能把 PFC、DC/DC、逆变器、电机、采样、通信和保护作为一个系统设计，而不是割裂章节。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/advanced/system-methodology/SYS-07-assessment.md","filePath":"content/motor/advanced/system-methodology/SYS-07-assessment.md","lastUpdated":1783096495000}'),s={name:"content/motor/advanced/system-methodology/SYS-07-assessment.md"};function n(d,t,l,i,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="sys-07-电源-电控联合系统设计-知识检查" tabindex="-1">SYS-07 电源-电控联合系统设计 - 知识检查 <a class="header-anchor" href="#sys-07-电源-电控联合系统设计-知识检查" aria-label="Permalink to &quot;SYS-07 电源-电控联合系统设计 - 知识检查&quot;">​</a></h1><p><strong>模块编号：</strong> SYS-07<br><strong>题目数量：</strong> 8<br><strong>验收目标：</strong> 能把 PFC、DC/DC、逆变器、电机、采样、通信和保护作为一个系统设计，而不是割裂章节。</p><hr><h2 id="_1-功率流" tabindex="-1">1. 功率流 <a class="header-anchor" href="#_1-功率流" aria-label="Permalink to &quot;1. 功率流&quot;">​</a></h2><p><strong>问题：</strong> 写出典型电源-电控系统的功率流。</p><p><strong>参考答案：</strong> 电网/电池输入 -&gt; PFC 或前级保护 -&gt; DC/DC 或直流母线 -&gt; 三相逆变器 -&gt; 电机 -&gt; 机械负载。辅助电源为 MCU、驱动、采样和通信供电。</p><hr><h2 id="_2-故障流" tabindex="-1">2. 故障流 <a class="header-anchor" href="#_2-故障流" aria-label="Permalink to &quot;2. 故障流&quot;">​</a></h2><p><strong>问题：</strong> 母线过压故障应同时影响哪些模块？</p><p><strong>答案：</strong> 前级 PFC/制动/放电路径、逆变器 PWM 使能、lxfoc 保护状态机、上位机告警、trace 记录和人工复位策略。</p><hr><h2 id="_3-调试顺序" tabindex="-1">3. 调试顺序 <a class="header-anchor" href="#_3-调试顺序" aria-label="Permalink to &quot;3. 调试顺序&quot;">​</a></h2><p><strong>问题：</strong> 为什么不能先满功率运行电机再调 PFC？</p><p><strong>参考答案：</strong> 未验证的前级母线可能在负载阶跃下欠压、过压或纹波过大，导致逆变器限幅、过流或器件应力超限。系统调试必须从低风险、可隔离的功率级开始。</p><hr><h2 id="_4-接口边界" tabindex="-1">4. 接口边界 <a class="header-anchor" href="#_4-接口边界" aria-label="Permalink to &quot;4. 接口边界&quot;">​</a></h2><p><strong>问题：</strong> 电控知识库工具链与 lxfoc 的职责边界是什么？</p><p><strong>答案：</strong> 电控知识库工具链负责理论、证据链、仿真、配置导出和 trace 分析；lxfoc 负责硬件无关算法、配置结构、运行时 telemetry 和 bench/selftest。硬件驱动和功率级保护由目标工程适配。</p><hr><h2 id="_5-闭环工作流" tabindex="-1">5. 闭环工作流 <a class="header-anchor" href="#_5-闭环工作流" aria-label="Permalink to &quot;5. 闭环工作流&quot;">​</a></h2><p><strong>任务：</strong> 写出“知识库仿真 -&gt; 算法库部署 -&gt; 数据回传比对”的最小步骤。</p><p><strong>参考答案：</strong></p><ol><li>在知识模块完成参数选择和仿真。</li><li>导出 <code>lxfoc_config.json</code>、<code>.h/.c</code> 和 <code>experiment_manifest.json</code>。</li><li>将配置放入 lxfoc 目标工程并编译。</li><li>运行实物实验并输出 <code>lxfoc_trace.csv</code>。</li><li>导入知识库，生成超调、稳定时间、稳态误差、duty 合法性和故障报告。</li><li>将报告回填到模块证据链。</li></ol><hr><h2 id="_6-验收阈值" tabindex="-1">6. 验收阈值 <a class="header-anchor" href="#_6-验收阈值" aria-label="Permalink to &quot;6. 验收阈值&quot;">​</a></h2><p><strong>问题：</strong> 电流环阶跃的 70% 阶段默认验收阈值是什么？</p><p><strong>答案：</strong> 超调 <code>&lt; 15%</code>，稳定时间 <code>&lt; 5 ms</code>，稳态误差 <code>&lt; 3%</code>。特殊电机和采样频率可以配置，但必须在 manifest 中说明。</p><hr><h2 id="_7-发布状态" tabindex="-1">7. 发布状态 <a class="header-anchor" href="#_7-发布状态" aria-label="Permalink to &quot;7. 发布状态&quot;">​</a></h2><p><strong>问题：</strong> <code>reviewed</code> 与 <code>verified</code> 在系统方法论中的区别是什么？</p><p><strong>答案：</strong> <code>reviewed</code> 表示理论和仿真证据经过技术审核；<code>verified</code> 表示完成实测或可复现实验闭环，并有 trace、报告和审核记录。</p><hr><h2 id="_8-风险边界" tabindex="-1">8. 风险边界 <a class="header-anchor" href="#_8-风险边界" aria-label="Permalink to &quot;8. 风险边界&quot;">​</a></h2><p><strong>问题：</strong> 高压电源专题为什么不能直接标记为 <code>verified</code>？</p><p><strong>参考答案：</strong> 高压实验存在人身和设备风险，必须先完成隔离、限功率、低压等效或合规台架验证。没有可追溯实验数据时，只能标记为 <code>reviewed</code> 或 <code>draft</code>。</p><hr><h2 id="评分" tabindex="-1">评分 <a class="header-anchor" href="#评分" aria-label="Permalink to &quot;评分&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th style="text-align:right;">得分</th><th>评价</th></tr></thead><tbody><tr><td style="text-align:right;">7-8</td><td>可参与系统级联调和发布审核</td></tr><tr><td style="text-align:right;">5-6</td><td>需要补齐接口边界和验证流程</td></tr><tr><td style="text-align:right;">&lt;5</td><td>需要重新学习系统调试方法</td></tr></tbody></table></div>',38)])])}const m=e(s,[["render",n]]);export{p as __pageData,m as default};
